t"},"expected_current_end_locator":{"basis":"next-segment-start","exclusive":true,"boundary_role":"end","next_segment_key":"1f61d597e45d1ba82a2b1c47","next_source_key":"29d0ac724fb21e9b","next_start_locator":{"basis":"canonical-source-map","source_node_id":"a-genese:section:29d0ac724fb21e9b","source_pdf_page":8,"printed_page":null,"locator":{"type":"printed_page","value":336},"boundary_role":"start"}},"approved_successor_start_locator":{"basis":"canonical-source-map","source_node_id":"a-genese:section:29d0ac724fb21e9b","source_pdf_page":8,"printed_page":null,"locator":{"type":"printed_page","value":336},"boundary_role":"start"},"approved_pair_metadata":{"current_source_pdf_page":337,"successor_source_pdf_page":337,"current_precedes_successor":true}},{"operation_id":"pr0048-131349adb8198c27153e9f66","decision_id":"131349adb8198c27153e9f66","resolution_id":null,"packet_id":"same-page-no-semantic-anchor-book-5-packet-01","book_id":5,"book_slug":"a-genese","segment_key":"cc17fbf1ec2b82c33161adc6","segment_order":127,"successor_segment_key":"0eaec0c3845dfb20216c9aed","successor_segment_order":128,"outcome":"confirm-successor-start","operation_type":"confirm_successor_start","reviewer_confidence":"high","source_artifact":"content/migration/reading-segment-remaining-no-anchor-backlog-adjudication-decisions.json","resolution_artifact":null,"expected_current_start_locator":{"basis":"canonical-source-map","source_node_id":"a-genese:section:eaf010e15ee2cfe1","source_pdf_page":8,"printed_page":null,"locator":{"type":"printed_page","value":340},"boundary_role":"start"},"expected_current_end_locator":{"basis":"next-segment-start","exclusive":true,"boundary_role":"end","next_segment_key":"0eaec0c3845dfb20216c9aed","next_source_key":"7f32e6b3db1a84c5","next_start_locator":{"basis":"canonical-source-map","source_node_id":"a-genese:section:7f32e6b3db1a84c5","source_pdf_page":8,"printed_page":null,"locator":{"type":"printed_page","value":340},"boundary_role":"start"}},"approved_successor_start_locator":{"basis":"canonical-source-map","source_node_id":"a-genese:section:7f32e6b3db1a84c5","source_pdf_page":8,"printed_page":null,"locator":{"type":"printed_page","value":340},"boundary_role":"start"},"approved_pair_metadata":{"current_source_pdf_page":341,"successor_source_pdf_page":341,"current_precedes_successor":true}}]$vereda_pr0048_targets$::jsonb
  ) as target (
    operation_id text,
    decision_id text,
    resolution_id text,
    packet_id text,
    book_id integer,
    book_slug text,
    segment_key text,
    segment_order integer,
    successor_segment_key text,
    successor_segment_order integer,
    outcome text,
    operation_type text,
    reviewer_confidence text,
    source_artifact text,
    resolution_artifact text,
    expected_current_start_locator jsonb,
    expected_current_end_locator jsonb,
    approved_successor_start_locator jsonb,
    approved_pair_metadata jsonb
  )
),
blocking_checks as (
  select
  'target-count'::text as check_key,
  'blocking'::text as severity,
  ((select count(*) from targets) = 133) as passed,
  (select count(*) from targets)::text as actual_value,
  '{}'::jsonb as details
union all
select
  'unique-operation-ids'::text as check_key,
  'blocking'::text as severity,
  ((select count(*) from targets) = (select count(distinct operation_id) from targets)) as passed,
  (select count(*) - count(distinct operation_id) from targets)::text as actual_value,
  '{}'::jsonb as details
union all
select
  'unresolved-excluded'::text as check_key,
  'blocking'::text as severity,
  (not exists (select 1 from targets where outcome = 'unresolved')) as passed,
  (select count(*) from targets where outcome = 'unresolved')::text as actual_value,
  '{}'::jsonb as details
union all
select
  'source-rows-present'::text as check_key,
  'blocking'::text as severity,
  ((select count(*) from targets target join content_staging.reading_segments segment on segment.run_id = 'adcff561-8f92-545c-a219-615818a454f4'::uuid and segment.book_id = target.book_id and segment.segment_key = target.segment_key) = 133) as passed,
  (select count(*) from targets target join content_staging.reading_segments segment on segment.run_id = 'adcff561-8f92-545c-a219-615818a454f4'::uuid and segment.book_id = target.book_id and segment.segment_key = target.segment_key)::text as actual_value,
  '{}'::jsonb as details
union all
select
  'successor-rows-present'::text as check_key,
  'blocking'::text as severity,
  ((select count(*) from targets target join content_staging.reading_segments segment on segment.run_id = 'adcff561-8f92-545c-a219-615818a454f4'::uuid and segment.book_id = target.book_id and segment.segment_key = target.successor_segment_key) = 133) as passed,
  (select count(*) from targets target join content_staging.reading_segments segment on segment.run_id = 'adcff561-8f92-545c-a219-615818a454f4'::uuid and segment.book_id = target.book_id and segment.segment_key = target.successor_segment_key)::text as actual_value,
  '{}'::jsonb as details
union all
select
  'not-already-applied'::text as check_key,
  'blocking'::text as severity,
  (not exists (select 1 from content_staging.migration_audit_events where run_id = 'adcff561-8f92-545c-a219-615818a454f4'::uuid and event_type = 'pr0048-reviewed-boundary-operation-applied')) as passed,
  (select count(*) from content_staging.migration_audit_events where run_id = 'adcff561-8f92-545c-a219-615818a454f4'::uuid and event_type = 'pr0048-reviewed-boundary-operation-applied')::text as actual_value,
  '{}'::jsonb as details
),
assertions as (
  select case
    when exists (select 1 from blocking_checks where not passed)
    then raise_exception('PR-0048 reviewed boundary application preconditions failed')
    else true
  end as passed
),
updated as (
  update content_staging.reading_segments segment
  set
    approval_status = 'content-review',
    end_locator = jsonb_set(
      coalesce(segment.end_locator, '{}'::jsonb),
      '{pr0048_reviewed_boundary_application}',
      jsonb_build_object(
        'operation_id', target.operation_id,
        'decision_id', target.decision_id,
        'operation_type', target.operation_type,
        'successor_segment_key', target.successor_segment_key
      ),
      true
    ),
    updated_at = now()
  from targets target, assertions
  where segment.run_id = 'adcff561-8f92-545c-a219-615818a454f4'::uuid
    and segment.book_id = target.book_id
    and segment.segment_key = target.segment_key
    and segment.approval_status = 'boundary-review'
  returning target.operation_id
),
update_count as (
  select case
    when (select count(*) from updated) = 133
    then true
    else raise_exception('PR-0048 reviewed boundary application updated an unexpected row count')
  end as passed
)
insert into content_staging.migration_audit_events (
  run_id,
  event_type,
  event_payload
)
select
  'adcff561-8f92-545c-a219-615818a454f4'::uuid,
  'pr0048-reviewed-boundary-operation-applied',
  to_jsonb(target)
from targets target, update_count;

commit;
